-- 📚 꼭집 주거 사전 — 완화 모집(입주자격 완화) · 국민·행복·영구 · 2026
-- 재계산 SQL(관리 API에서 그대로 실행 · 읽기만). 범위: 공고일 2026년 · 유형은 housing_type_map 표준값.
-- 확인 2026-10-13 · 실행 4.0초 · 결과:
-- {"anns": 38, "by_std": {"국민임대": 20, "매입임대": 1, "영구임대": 5, "행복주택": 12}, "소득자산배제": 26, "소득자산배제_ex": ["20750_경상북도_구미시", "2015122300020898", "2015122300020893"], "150%": 9, "150%_ex": ["2015122300020899", "2015122300020744", "2015122300020730"], "무주택간주": 10, "무주택간주_ex": ["2015122300020898", "2015122300020893", "2015122300020871"], "재계약제한": 29, "재계약제한_ex": ["20750_경상북도_구미시", "2015122300020899", "2015122300020898"], "선착순": 0, "선착순_ex": null}
with a as(select distinct on(x.announcement_id)x.announcement_id,x.supply_org org,coalesce(m.std_type,x.housing_type)std,extract(year from coalesce(x.announcement_date,x.created_at::date))::int yr from announcements x left join housing_type_map m on m.source_table='announcements' and m.source=x.source and m.housing_type=x.housing_type order by x.announcement_id,(x.source='LH')desc,x.created_at desc),y as(select p.announcement_id,regexp_replace(p.content_raw,'\s+',' ','g')t,coalesce(r.class_name,c.class_name)cls,a.org,a.std from announcement_policies p join a using(announcement_id) left join policy_row_classes r on r.policy_id=p.id and r.axis='standard' left join policy_category_classes c on c.category=p.category and c.axis='standard' where a.yr=2026)select json_build_object('anns',(select count(distinct announcement_id) from y where cls='완화 모집'),'by_std',(select json_object_agg(std,n) from(select std,count(distinct announcement_id)n from y where cls='완화 모집' group by 1)q),'소득자산배제',(select count(distinct announcement_id) from y where cls='완화 모집' and t~'(소득|자산)[^.]{0,30}(배제|미적용|적용하지\s*않|관계없이|무관)'),'소득자산배제_ex',(select json_agg(i) from(select distinct announcement_id i from y where cls='완화 모집' and t~'(소득|자산)[^.]{0,30}(배제|미적용|적용하지\s*않|관계없이|무관)' order by 1 desc limit 3)q),'150%',(select count(distinct announcement_id) from y where cls='완화 모집' and t~'150\s*%'),'150%_ex',(select json_agg(i) from(select distinct announcement_id i from y where cls='완화 모집' and t~'150\s*%' order by 1 desc limit 3)q),'무주택간주',(select count(distinct announcement_id) from y where cls='완화 모집' and t~'무주택(으로)?\s*간주'),'무주택간주_ex',(select json_agg(i) from(select distinct announcement_id i from y where cls='완화 모집' and t~'무주택(으로)?\s*간주' order by 1 desc limit 3)q),'재계약제한',(select count(distinct announcement_id) from y where cls='완화 모집' and t~'(완화|자격완화)[^.]{0,80}재계약'),'재계약제한_ex',(select json_agg(i) from(select distinct announcement_id i from y where cls='완화 모집' and t~'(완화|자격완화)[^.]{0,80}재계약' order by 1 desc limit 3)q),'선착순',(select count(distinct announcement_id) from y where cls='완화 모집' and t~'선착순'),'선착순_ex',(select json_agg(i) from(select distinct announcement_id i from y where cls='완화 모집' and t~'선착순' order by 1 desc limit 3)q))j;
